def report(rows, tenant, ids):
    if not ids:
        return []
    try:
        first_rows = {}
        for row in rows:
            if row["tenant"] == tenant:
                first_rows.setdefault(row["id"], row)
        return [first_rows[key]["value"] if key in first_rows else None for key in ids]
