import unittest
from report import report
from original import report as reference

class ReportContract(unittest.TestCase):
    def setUp(self):
        self.rows = [
            {"tenant": "north", "id": "a", "value": 10},
            {"tenant": "south", "id": "a", "value": 20},
            {"tenant": "north", "id": "a", "value": 30},
            {"tenant": "north", "id": "b", "value": 40},
        ]

    def test_first_match_and_query_order(self):
        self.assertEqual(report(self.rows, "north", ["b", "a", "missing", "a"]), [40, 10, None, 10])

    def test_tenant_isolation(self):
        self.assertEqual(report(self.rows, "north", ["a"]), [10])
        self.assertEqual(report(self.rows, "south", ["a"]), [20])

    def test_updated_records_on_next_request(self):
        self.assertEqual(report(self.rows, "north", ["a"]), [10])
        self.rows[0]["value"] = 99
        self.assertEqual(report(self.rows, "north", ["a"]), [99])

    def test_new_records_on_next_request(self):
        report(self.rows, "north", ["a"])
        self.assertEqual(report([], "north", ["a"]), [None])

    def test_empty_query_and_absent_tenant(self):
        self.assertEqual(report(self.rows, "north", []), [])
        self.assertEqual(report(self.rows, "absent", ["a"]), [None])

    def test_input_is_not_mutated(self):
        before = [dict(row) for row in self.rows]
        report(self.rows, "north", ["a", "b"])
        self.assertEqual(self.rows, before)

    def test_replay_against_reference(self):
        from dataset import workload
        rows, tenant, queries = workload()
        self.assertEqual(report(rows, tenant, queries), reference(rows, tenant, queries))

if __name__ == "__main__":
    unittest.main()

